<script>function saldo(){let v=Math.max(0,(parseFloat($('#valor_total').val())||0)-(parseFloat($('#valor_abono').val())||0));$('#saldo').val('$ '+v.toLocaleString('es-CO',{minimumFractionDigits:2,maximumFractionDigits:2}));} $('#valor_total,#valor_abono').on('input',saldo);$('#reservaForm').on('submit',function(e){e.preventDefault();$.post('{{ route('alquileres.reservar.store') }}',$(this).serialize()).done(r=>_alertGeneric('success','Reserva creada',r.message,'{{ route('alquileres.dashboard') }}')).fail(x=>_alertGeneric('error','Error',x.responseJSON?.error || 'Revise la información ingresada.'));});</script>
